#define _GNU_SOURCE
#include <stdio.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <sys/socket.h>
#include <linux/net.h>  // Provides SYS_SOCKET constant on some systems
#include <errno.h>

// We must define SYS_socketcall if not automatically included
#ifndef SYS_socketcall
#define SYS_socketcall 102 // Common x86 32-bit number
#endif

int main() {
    int sock_fd;

    // 1. Define the parameters for socket(AF_INET, SOCK_STREAM, 0)
    unsigned long args[3];
    args[0] = AF_INET;     // Address Family (IPv4)
    args[1] = SOCK_STREAM; // Socket Type (TCP)
    args[2] = 0;           // Protocol (default)

    // 2. Invoke socketcall via syscall(2)
    // Parameters: SYS_socketcall, SYS_SOCKET, pointer to args array
    printf("Attempting to create socket using socketcall...
");
    sock_fd = syscall(SYS_socketcall, SYS_SOCKET, args);

    if (sock_fd == -1) {
        perror("socketcall failed");
        return 1;
    }

    printf("Socket created successfully. File Descriptor: %d\n", sock_fd);

    // Clean up
    close(sock_fd);
    return 0;
}
